import 'package:flutter/material.dart';

class EcommercePage extends StatelessWidget {
  EcommercePage({super.key});
  final List<Map<String, String>> products = [
    {
      'name': 'Shoes',
      'image':
          'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRe_fKlZDshCxMus6UNFpFvrbbxWM5GYPB6kQ&s',
      'subtitle': 'Comfortable running shoes'
    },
    {
      'name': 'Watch',
      'image':
          'data:image/jpeg;base64,',
      'subtitle': 'Luxury wrist watch'
    },
    {
      'name': 'Laptop',
      'image':
          'data:image/jpeg;base64,',
      'subtitle': 'Stylish Laptops'
    },
    {
      'name': 'Bag',
      'image':
          'data:image/jpeg;base64,',
      'subtitle': 'Stylish Bags'
    },
    {
      'name': 'Barbuds ',
      'image':
          'data:image/jpeg;base64,',
      'subtitle': 'Stylish Earbuds '
    },
  ];
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Center(child: Text('E-Commerce UI'))),
      body: Column(
        children: [
          Expanded(
            child: ListView.builder(
              itemCount: products.length,
              itemBuilder: (context, index) {
                var product = products[index];
                return Card(
                    margin: EdgeInsets.symmetric(horizontal: 10, vertical: 7),
                    child: ListTile(
                      contentPadding: EdgeInsets.all(12),
                      leading: CircleAvatar(
                        backgroundImage: NetworkImage(product['image']!),
                      ),
                      title: Text(product['name']!),
                      subtitle: Text(product['subtitle'] ?? ''),
                      trailing: ElevatedButton(
                        onPressed: () {},
                        child: Text('Details'),
                      ),
                    ));
              },
            ),
          ),
          Container(
            padding: EdgeInsets.all(16),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                Expanded(
                  child: ElevatedButton(
                    onPressed: () {},
                    child: Text('Add to Cart'),
                  ),
                ),
                SizedBox(width: 16),
                Expanded(
                  child: ElevatedButton(
                    onPressed: () {},
                    child: Text('Wishlist'),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
